Rule.Source:


import sailpoint.object.Filter;
import sailpoint.object.Link;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AccountRequest.Operation;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningProject;
import sailpoint.object.QueryOptions;
import sailpoint.service.LinkService;
import sailpoint.tools.Util;

        // find out the new password
        String identityName = project.getIdentity();
        ProvisioningPlan plan = project.getMasterPlan();
        if (plan == null) {
            log.warn("Project is null");
            return project; // nothing to do
        }
        List<AccountRequest> acctRequests = plan.getAccountRequests();
        if (acctRequests.size() != 1) {
            log.warn("AccountRequests size: " + acctRequests.size());
            return project; // nothing to do or too much to do
        }
        String newPassword = null;
        AccountRequest acctRequest = acctRequests.get(0);
        for (AttributeRequest attr : acctRequest.getAttributeRequests()) {
            if (attr.getName().equals(("password"))) {
                newPassword = (String)attr.getValue();
                log.warn("newPassword: " + newPassword);
            }
        }
        if (Util.isNullOrEmpty(newPassword)) {
            log.warn("newPassword is null");
            return project; // nothing to do
        }

        // get the Links for this Identity for all apps with passwords
        LinkService linkSvc = new LinkService(context);
        Set<String> passApps = linkSvc.getProvisioningApplications(true);
        log.warn("passApps: " + passApps);
        QueryOptions ops = new QueryOptions();
        ops.add(Filter.eq("identity.name", identityName));
        ops.add(Filter.in("application.id", passApps));
        List<Link> links = context.getObjects(Link.class, ops);
        for (Link link : links) {
            log.warn("next Link: " + link);
            String appName = link.getApplicationName();
            if (appName.equals(acctRequest.getApplicationName())) {
                log.warn("Skipping link for " + appName);
                continue;
            }
            AccountRequest newAcctReq = new AccountRequest(acctRequest);
            newAcctReq.setOperation(Operation.Modify);
            newAcctReq.setNativeIdentity(link.getNativeIdentity());
            newAcctReq.setApplication(link.getApplicationName());
            plan.add(newAcctReq);
        }
        log.warn("Updated plan: " + plan.toXml());

        return project;
